      "id": "story-trigger",
      "title": "「扳机」 · 代理人档案",
      "summary": "「扳机」，新艾利都防卫军·黑曜石营·奥波勒斯小队的狙击手。「扳机」是其于艾利都时期入伍所持有的代号，一直沿用至今。 有着极其特殊的双眼，虽然无法看到绝大部分事物，但在空洞环境下可以清晰辨别一切具备以太波动事物的方位与变化。注意：具备以太波动的事物，泛指生命体、原生以太物质、…",
