      "id": "story-seed",
      "title": "「席德」 · 代理人档案",
      "summary": "「席德」，新艾利都防卫军·黑曜石营·奥波勒斯小队的火炮手。本名芙罗拉，「席德」这一代号继承自其监护人、防卫军战斗用智能构造体「席德」，后者已将代号变更为「老席德」。 根据多方证言，「席德」是「老席德」于旧都陷落时，从零号空洞内营救出的、身份不明的孤儿，「老席德」收养了她并在…",
