      "title": "11号 · 代理人档案",
      "summary": "「11号」是新艾利都防卫军的成员，现属于黑曜石营中奥波勒斯小队，担任主攻手。「11号」是她在军队中的代号，其自称早已舍弃了真实的姓名。 「11号」似乎很喜欢辛辣口味的食物，对锦鲤面馆的超辣拉面情有独钟。值得一提的是，目前她每次和我们打招呼时，都会叫出不同的名字。 主人，根据…",
