      "title": "艾莲·乔 · 代理人档案",
      "summary": "艾莲，维多利亚家政女仆，也是最后一位加入组织的成员。 节能主义，几乎不喜欢一切需要耗费精力的事情。但在队友们的配合下，可以在关键时刻充分发挥自身的强大战力。 战斗方式具有高耗能特质，通常需要补充糖分，常把棒棒糖叼在嘴里。 虽然嘴上总是说着「麻烦，想换工作」，实际上非常珍惜现…",
