      "summary": "爱丽丝·泰姆菲尔德，怪啖屋的新晋成员，新艾利都名门泰姆菲尔德家族的千金大小姐。 爱丽丝自幼修习击剑与以太科学，在以上领域表现出优秀的天赋。她当前就读于高志院下属的圣星女子学院，是一名品学兼优的标准优等生；推定，其有朝一日会继承家业，成为新艾利都新世代的以太学者。 她极为重视…",
