      "title": "伊德海莉・墨菲 · 代理人档案",
      "summary": "伊德海莉，除了代理人的身份外，也兼任绳匠以及怪啖屋的投稿作者。 在其他人看来，伊德海莉在寻常情况下待人处事总有种闲适的慵懒感，不过就记录的资料来判断，相较于慵懒这样的描述，她更像在被一种与周遭环境格格不入的虚无感所包裹。 或许对多数人而言，这是沉浸创作之人的通病——作为天赋…",
